<?php

namespace LLPhant\Tool;

use Exception;
use Http\Discovery\Psr17Factory;
use Http\Discovery\Psr18ClientDiscovery;
use LLPhant\Render\CLIOutputUtils;
use LLPhant\Render\OutputAgentInterface;
use LLPhant\Utility;
use Psr\Http\Client\ClientExceptionInterface;
use Psr\Http\Client\ClientInterface;
use Psr\Http\Message\RequestFactoryInterface;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\StreamFactoryInterface;

/**
 * Publishes HTML generated by an LLM to a public URL with deed.page (https://deed.page/docs).
 *
 * No API key is needed. The first publish returns an owner token, which this class keeps in memory
 * and sends on later publishes and deletes. It is never returned to the LLM: use getToken() to store
 * it yourself, or pass it back in through the constructor or the DEEDPAGE_TOKEN env var.
 */
class DeedPagePublisher extends ToolBase
{
    private const SLUG_PATTERN = '/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/';

    private ?string $token;

    private readonly ClientInterface $client;

    private readonly RequestFactoryInterface&StreamFactoryInterface $factory;

    /**
     * @param  int|null  $ttlSeconds  When set, published pages expire after this many seconds. Null keeps them.
     */
    public function __construct(
        ?string $token = null,
        bool $verbose = false,
        public OutputAgentInterface $outputAgent = new CLIOutputUtils(),
        ?ClientInterface $client = null,
        private readonly ?int $ttlSeconds = null,
        private readonly string $baseUri = 'https://deed.page',
    ) {
        parent::__construct($verbose);

        if ($ttlSeconds !== null && $ttlSeconds <= 0) {
            throw new Exception('ttlSeconds must be a positive number of seconds, or null to keep pages.');
        }

        $this->token = $token ?? Utility::readEnvironment('DEEDPAGE_TOKEN');
        $this->client = $client ?? Psr18ClientDiscovery::find();
        $this->factory = new Psr17Factory();
    }

    /**
     * Publish a complete, self-contained HTML page to a public URL and return that URL.
     * Anyone with the link can open the page, so never put secrets or private data in it.
     *
     * @param  string  $html  The full HTML document to publish, with any CSS and JavaScript inlined
     * @param  string  $slug  Optional name for the page address: lowercase letters, digits and hyphens. Leave empty for a random one
     *
     * @throws Exception|ClientExceptionInterface
     */
    public function publishHtml(string $html, string $slug = ''): string
    {
        $slug = trim($slug);
        if ($slug !== '' && preg_match(self::SLUG_PATTERN, $slug) !== 1) {
            $this->wasSuccessful = false;
            throw new Exception('Invalid slug "'.$slug.'": use 1-63 lowercase letters, digits and hyphens, without a leading or trailing hyphen.');
        }

        if ($this->verbose) {
            $this->outputAgent->renderTitleAndMessageOrange('🔧 Executing tool deed.page', $slug === '' ? 'publishing a page' : 'publishing '.$slug, true);
        }

        $body = ['files' => ['index.html' => $html]];
        if ($slug !== '') {
            $body['slug'] = $slug;
        }

        $request = $this->factory->createRequest('POST', $this->baseUri.'/v1/sites')
            ->withHeader('Content-Type', 'application/json')
            ->withHeader('Accept', 'application/json')
            ->withHeader('X-Client', 'LLPhant')
            ->withBody($this->factory->createStream(json_encode($body, JSON_THROW_ON_ERROR)));
        if ($this->ttlSeconds !== null) {
            $request = $request->withHeader('X-Ttl', (string) $this->ttlSeconds);
        }
        if ($this->token !== null) {
            $request = $request->withHeader('Authorization', 'Bearer '.$this->token);
        }

        $result = $this->decode($this->client->sendRequest($request), 'publish');

        $url = $result['url'] ?? null;
        if (! is_string($url) || $url === '') {
            $this->wasSuccessful = false;
            throw new Exception('deed.page publish response did not contain a URL.');
        }

        if ($this->token === null && isset($result['token']) && is_string($result['token']) && $result['token'] !== '') {
            $this->token = $result['token'];
        }

        $this->lastResponse = $url;
        $this->wasSuccessful = true;
        if ($this->verbose) {
            $this->outputAgent->render('Page published at '.$url, true);
        }

        return $url;
    }

    /**
     * Delete a page this publisher owns. Meant for application code; it is not designed to be offered to the LLM.
     *
     * @throws Exception|ClientExceptionInterface
     */
    public function deleteSite(string $slug): void
    {
        if ($this->token === null) {
            throw new Exception('Deleting a deed.page site needs the owner token from the publish that created it.');
        }
        if (preg_match(self::SLUG_PATTERN, $slug) !== 1) {
            throw new Exception('Invalid slug "'.$slug.'".');
        }

        $request = $this->factory->createRequest('DELETE', $this->baseUri.'/v1/sites/'.$slug)
            ->withHeader('Accept', 'application/json')
            ->withHeader('X-Client', 'LLPhant')
            ->withHeader('Authorization', 'Bearer '.$this->token);

        $this->decode($this->client->sendRequest($request), 'delete');
    }

    /**
     * The owner token for the pages published so far, or null before the first publish.
     * Store it privately to update or delete those pages later. Do not show it to the LLM or log it.
     */
    public function getToken(): ?string
    {
        return $this->token;
    }

    /**
     * @return array<string, mixed>
     *
     * @throws Exception
     */
    private function decode(ResponseInterface $response, string $action): array
    {
        $raw = (string) $response->getBody();
        try {
            $decoded = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException $e) {
            $this->wasSuccessful = false;
            throw new Exception('deed.page '.$action.' returned HTTP '.$response->getStatusCode().' with a non-JSON body.', $response->getStatusCode(), $e);
        }

        if (! is_array($decoded)) {
            $this->wasSuccessful = false;
            throw new Exception('deed.page '.$action.' returned an unexpected response.');
        }

        /** @var array<string, mixed> $decoded */
        if ($response->getStatusCode() >= 400 || ($decoded['ok'] ?? false) !== true) {
            $this->wasSuccessful = false;
            $code = is_string($decoded['code'] ?? null) ? $decoded['code'] : (is_string($decoded['error'] ?? null) ? $decoded['error'] : 'error');
            $message = is_string($decoded['message'] ?? null) ? $decoded['message'] : 'no message';
            throw new Exception('deed.page '.$action.' failed (HTTP '.$response->getStatusCode().', '.$code.'): '.$message, $response->getStatusCode());
        }

        return $decoded;
    }
}
